import fs from 'node:fs';
import { gunzipSync } from 'node:zlib';
import { describe, expect, it } from 'vitest';
import { assertFormalizationReferenceResult, type FormalizationReferenceInput } from '../src/math/formalizationReference';
import { canonicalMathJson, mathDigest } from '../src/math/mathRuntimeIo';

// Real native Lean receipt from finite-family-v4-fixed, proofnet_test_003 /
// Artin|exercise_3_7_2. Sources come from the original approved campaign state
// and manifest-bound reference; no comparison is regenerated by this test.
// Original manifest SHA256: 542fdabead40e7fbe52505a35f604c9b5f5baa72598cf977bb058e021cd46f09
// Original state SHA256: 13b90aaae949b58002d3f34318e78d1ff657019d40cf4a18a2e1ed4c3373ab72
const fixtureSha256 = 'ff4bfcde4ceb0c985cd98ed4ef2381b257b5dbf934e40ad683a470d95c477f1e';
const receiptSha256 = 'fbe1a1181c2339163a83640523564436baff56c14ac56c2f8795317133eeff03';
const inputDigest = '9c02cd5ceb679d0218f048a97d87462e87e74503721cf74254a428fbb9204b4c';

function fixture() {
  const compressed = fs.readFileSync(new URL('./fixtures/formalization-reference-v4-proofnet003.json.gz', import.meta.url));
  expect(mathDigest(compressed)).toBe(fixtureSha256);
  const saved = JSON.parse(gunzipSync(compressed).toString('utf8')) as
    { input: FormalizationReferenceInput; receiptText: string };
  expect(mathDigest(saved.receiptText)).toBe(receiptSha256);
  expect(mathDigest(canonicalMathJson(saved.input))).toBe(inputDigest);
  return { input: saved.input, receipt: JSON.parse(saved.receiptText) };
}

describe('saved finite-family correspondence method compatibility', () => {
  it('accepts an unchanged real v4 receipt against its exact frozen input', () => {
    const { input, receipt } = fixture();
    expect(receipt).toMatchObject({ schema: 'theoremos.formalization-reference.v3',
      method: 'finite-family-correspondence-v4', check: 'completed', status: 'established',
      modelInvoked: false, proofVerified: false, semanticEquivalenceClaimed: false });
    const report = JSON.parse(receipt.evidence.reportText);
    expect(report.schema).toBe('theoremos.reference-report.v3');
    expect(report.pairs[0].transformations).toEqual([
      expect.objectContaining({ ruleId: 'finite-family-reindex', ruleVersion: 1 }),
    ]);
    expect(() => assertFormalizationReferenceResult(input, receipt)).not.toThrow();
  });

  it.each(['method', 'schema', 'schema-and-method'])(
    'rejects relabeling a saved v4 %s as the cardinality method', mutation => {
      const { input, receipt } = fixture();
      if (mutation !== 'schema') receipt.method = 'cardinality-correspondence-v5';
      if (mutation !== 'method') receipt.schema = 'theoremos.formalization-reference.v4';
      expect(() => assertFormalizationReferenceResult(input, receipt)).toThrow();
    });

  it('rejects a changed report even when its own digest is updated', () => {
    const { input, receipt } = fixture();
    const report = JSON.parse(receipt.evidence.reportText);
    report.pairs[0].transformations[0].before.expression += ' ';
    receipt.evidence.reportText = JSON.stringify(report);
    receipt.evidence.reportSha256 = mathDigest(receipt.evidence.reportText);
    expect(() => assertFormalizationReferenceResult(input, receipt)).toThrow();
  });

  it.each(['candidateSource', 'referenceSource'] as const)(
    'rejects a changed %s even when input digests are updated', source => {
      const { input, receipt } = fixture();
      expect(input[source]).toContain('≠');
      input[source] = input[source].replace('≠', '=');
      receipt[`${source}Sha256`] = mathDigest(input[source]);
      receipt.inputDigest = mathDigest(canonicalMathJson(input));
      expect(() => assertFormalizationReferenceResult(input, receipt)).toThrow();
    });

  it('rejects a changed generated query even when its own digest is updated', () => {
    const { input, receipt } = fixture();
    const query = receipt.files.find((file: { file: string }) => file.file === 'ReferenceComparison.lean');
    expect(query).toBeDefined();
    query.text += '\n-- changed query\n';
    query.sha256 = mathDigest(query.text);
    expect(() => assertFormalizationReferenceResult(input, receipt)).toThrow();
  });

  it('rejects a changed captured artifact even when its own digest is updated', () => {
    const { input, receipt } = fixture();
    receipt.evidence.artifacts[0].text += ' ';
    receipt.evidence.artifacts[0].digest = mathDigest(receipt.evidence.artifacts[0].text);
    expect(() => assertFormalizationReferenceResult(input, receipt)).toThrow();
  });
});
